/**
 * @method
 * @name getFormatDate
 * @description desc
 * @param {string} str desc
 * @hidden N
 * @exception 
 * @example ${example}
 */
scwin.getFormatDate = function (input, format) {
	// console.log(input + "||"+ format);
	let returnval = "";
	if (format === "yyyy-MM-dd HH:mm:ss") {
		if (input.length === 14) {
			returnval = input.substring(0, 4)
				+ "-" + input.substring(4, 6)
				+ "-" + input.substring(6, 8)
				+ " " + input.substring(8, 10)
				+ ":" + input.substring(10, 12)
				+ ":" + input.substring(12, 14)
				;
		} else {
			return input;
		}

	} else {
		if (input.length === 8) {
			returnval = input.substring(0, 4)
				+ "-" + input.substring(4, 6)
				+ "-" + input.substring(6, 8)

				;
		} else {
			return input;
		}
	}

    return returnval;
}

