/**
 * @method
 * @name isValidDate8
 * @description desc
 * @param str
 * @hidden N
 * @exception 
 * @example ${example}
 */
scwin.isValidDate8 = function (str) 
{

        if(str.length !== 8 )
        {
            return true;

        }else{

            const regx = /^\d{8}$/
            if(!regx.test(str)) return true;

            const year  =  Number(str.substring(0, 4));
            const month =  Number(str.substring(4, 6));
            const day   =  Number(str.substring(6, 8));

            const date = new Date(year, month -1 , day);

            return !((date.getFullYear() === year) &&
                     (date.getMonth()    === month - 1) && 
                     (date.getDate()     === day ) );
        }

}

/**
 * @method
 * @name isValidDate14
 * @description desc
 * @param str
 * @hidden N
 * @exception 
 * @example ${example}
 */
scwin.isValidDate14 = function (str) 
{

        if(str.length !== 14 )
        {
            return true;

        }else{
            const regx = /^\d{14}$/
            if(!regx.test(str)) return true;

            const year      =  Number(str.substring(0, 4));
            const month     =  Number(str.substring(4, 6));
            const day       =  Number(str.substring(6, 8));
            const hour      =  Number(str.substring(8, 10));
            const minutes   =  Number(str.substring(10, 12));
            const second    =  Number(str.substring(12, 14));

            const date = new Date(year, month -1 , day, hour, minutes, second);

            return !((date.getFullYear() === year) &&
                     (date.getMonth()    === month - 1) && 
                     (date.getDate()     === day ) &&
                     (date.getHour()     === hour) &&
                     (date.getMinutes()  === minutes) &&
                     (date.getSecond()   === second )
                     );
        }

}

/**
