 * @example ${example}
 */
scwin.checkDate = function (date, format) 
{
     if(format === "yyyyMMddHHmmss")
    {

        if(isValidDate14(date))
        {
            $c.win.alert($c.data.getMessage("calendar_check_length_one"));
            return true;
        }else{
            return false;
        }
    }
    else 
    {
        if(scwin.isValidDate8(date))
        {
            $c.win.alert($c.data.getMessage("calendar_check_length_one"));
            return true;
        }else{
            return false;
        }

    }
}
/**
 * @method
 * @name checkFromToDate
 * @description desc
 * @param start , end
 * @hidden N
 * @exception 
 * @example ${example}
 */
scwin.checkFromToDate = function (start, end) 
{
    // 20260730173053
    // 20260730

    // console.log("cal_len:"+ end +"||"+ end.length + "||"+start+ "||"+start.length+"||"+(parseInt(end) - parseInt(start)));
    if((end.length === 14) && (start.length === 14))
    {
        let spc = (parseInt(end) - parseInt(start));
        if( spc < 0 )
        {
            $c.win.alert($c.data.getMessage("calendar_check", "시작일", "종료일"));
            return true;
        }else{
            return false;
        }
    }
    else if((end.length === 8) && (start.length === 8))
    {
        let spc = (parseInt(end) - parseInt(start));
        if( spc < 0 )
        {
            $c.win.alert($c.data.getMessage("calendar_check", "시작일", "종료일"));
            return true;
        }else{
            return false;
        }

    }

    return false;

}

/**
 * @method
 * @name setFromToDateByOldYear
 * @description desc
 * @param start , end
 * @hidden N
 * @exception 
 * @example ${example}
 */
scwin.setFromToDateByOldYear = function (start, end, format) 
{
    // 20260730173053
    // 20260730
    // end 날짜는 오늘로 시작날짜는 1년전으로 

    if(format.length === 14)
    {
        let str = $c.date.getServerDateTime("yyyyMMddHHmmss");
        end.setValue(str);
        let year = Number( str.substring(0, 4));

        year = year - 1;

        const others =  str.substring(4, 14);

        const date = year + others;

        start.setValue(date);
    }
    else
    {

        let str = $c.mgt.getSysDate();
        end.setValue(str);
        let year = Number( str.substring(0, 4));

        year = year - 1;

        const others =  str.substring(4, 8);

        const date = year + others;

        start.setValue(date);
    }

}

/**
 * @method
 * @name setFromToDateByOldWeek
 * @description desc
 * @param start , end
 * @hidden N
 * @exception 
 * @example ${example}
 */
scwin.setFromToDateByOldWeek = function (start, end, format) 
{
    // 20260730173053
    // 20260730
    // end 날짜는 오늘로 시작날짜는 일주일전으로 

    const today = new Date();
    const weekAgo = new Date(today);
    weekAgo.setDate(today.getDate() - 7 );

    const yyyy = weekAgo.getFullYear();
    const mm   = String(weekAgo.getMonth() + 1).padStart(2, '0');
    const dd   = String(weekAgo.getDate()).padStart(2, '0');

    const result = yyyy + mm + dd;

    if(format.length === 14)
    {
        let str = $c.date.getServerDateTime("yyyyMMddHHmmss");
        end.setValue(str);

        str = str.substring(8);

        result = result + str;

        start.setValue(result);
    }
    else
    {

        let str = $c.mgt.getSysDate();
        end.setValue(str);

        start.setValue(result);
    }

}

/**
 * @method
 * @name spaceCheckFromToDate
 * @description desc
 * @param start , end, space
 * @hidden N
 * @exception 
 * @example ${example}
 */
scwin.spaceCheckFromToDate = function (start, end, space) 
{
    const d1 = new Date(start.substring(0,4), start.substring(4,6) - 1, start.substring(6,8));
    const d2 = new Date(end.substring(0,4), end.substring(4,6) - 1, end.substring(6,8));

    const diff = Math.abs(d2 - d1);
    const days = diff / (1000*60*60*24);

    // console.log(start+"||"+end+"||"+ diff +"||"+ days +"||"+ space);

     if( days > space )
    {
        $c.win.alert($c.data.getMessage("calendar_space", "시작일", "종료일", space));
        return true;
    }else{
        return false;
    }
}    

