	const filter = /^([\w-\.]+)@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.)|(([\w-]+\.)+))([a-zA-Z]{2,4}|[0-9]{1,3})(\]?)$/;

    console.log(str +"||"+  filter.test( str ));
    if ( filter.test( str ) ) {
		return false;
	}

    $c.win.alert($c.data.getMessage("mgt_validMail"));                    
	return true;
}

