 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.getObjectValue = function (obj) {
	if (typeof obj !== "object") {
		return;
	}

	if (typeof obj.getValue !== "undefined" && typeof obj.getValue === "function") {
		return scwin.trim(obj.getValue());
	}
	return;
}

/**
 * @method
 * @name validateGroup
 * @description 웹스퀘어 속성을 가지고 Validation을 처리
 * @param {object} groupId 그룹ID 객체
 * @returns {boolean} 결과
 * @hidden N
 * @exception
 * @migrationStatus
 * @example 속성 정보
 *          mandatory : 필수 여부
 *          title     : 오류 메시지에 뿌려줄 객체 명
 *          minlength : 최소 입력 값 길이
 * 
 */

scwin.validateGroup = function (groupId) {

    const group = $p.getComponentById(groupId);

    if (group) {
        // Input 관련된 객체만 조회
        let comps = scwin.getChildrenFind(group);        
        for (let i = 0; i < comps.length; i++) {
            let comp = comps[i];

            // 값 가져오기
            const value = comp.getValue ? comp.getValue() : "";
            // Title (없으면 id로 대체)
            const title = comp.getAttribute("title") || comp.id;

            const josa =  $c.str.isFinalConsonant($p, String(title)) ? "을" : "를";       

            // 필수 체크
            if (comp.getAttribute("mandatory")) 
            {                                
                if ($c.util.isEmpty(value)) 
                {  

                    $c.win.alert($c.data.getMessage("mgt_input", title, josa),function () { comp.focus(); });                    

                    return true;
                }                

                if (comp.getAttribute("minlength") && comp.getAttribute("minlength") > 0) {
                    if (value.length < comp.getAttribute("minlength")) {
                        let typeNm = "문자";
                        if (comp.getAttribute("dataType") === "number") {
                            typeNm = "숫자";
                        }

                        $c.win.alert($c.data.getMessage("mgt_have_length", title, josa, typeNm, comp.getAttribute("minlength")),function () { comp.focus(); });        

                        return true;
                    }
                }
            }        
        }
    }    
    return false;
}

/**
 * @method
 * @name getChildrenFind
 * @description Group 태그 안에서 input, select 등 입력 객체를 찾아 배열로 생성
 * @param {object} comp Group 객체
 * @returns {object} Input, Select등 입력 하는 객체
 * @hidden N
 * @exception
 * @migrationStatus
 * @example
 */

scwin.getChildrenFind = function (comp) {

    let result = [];
    function loop(c) {

        if (!c || !c.getChildren) return;
        const children = c.getChildren();
        for (let i = 0; i < children.length; i++) {
            const child = children[i];

            if (child.setValue && child.getValue) {
                result.push(child);
            }
            loop(child);
        }
    }
    loop(comp);

    return result;
};

/**
 * @method
 * @name scwin.setClear
 * @description 웹스퀘어 속성을 가지고 select/input reset
 * @param {object} groupId 그룹ID 객체name
 * @returns 
 * @hidden N
 * @exception
 * @migrationStatus

 */

scwin.setClear = function (groupId) {

    const group = $p.getComponentById(groupId);

    if (group) 
    {
        // Input 관련된 객체만 조회
        let comps = scwin.getChildrenFind(group);        

        for (let i = 0; i < comps.length; i++)
        {

            let comp = comps[i];

            if(comp.getSelectedIndex)
            {
                comp.setSelectedIndex(0);
            }else{

                if(comp._wTagName === "input") comp.setValue("");

            }

        }  
    }else{
        console.log("cant search grid!!!");
    }    
    return ;
}

/**
 * @method
 * @name downloadProc
 * @description 엑셀 다운로드및 파일 다운로드 시 iframe 형식으로 받을때 필수로 
 * 생성되는 객체를 처리
 * @param {string} url 호출 서버 경로
 * @param {object} params 파라미터 정보
 * @param {string} errorMsg 에러 메시지
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example
 */

scwin.downloadProc = function (url, params, msg) {

    const params_ = new URLSearchParams();    
    // 셋팅 처리
    if (params != null && params !== "") {
        Object.entries(params).forEach(([key, value]) => {  
            params_.append(
                key,
                value == null ? "":value
            );
        });
    }

    fetch(url + "?" + params_, {
        method: "GET"
    }).then (function (res) {
        if (!res.ok) {
            throw new Error("파일다운로드 실패(" + res.statusText + ")");
        }

        let fileName = "";
        // 파일명 검색
        const disposition = res.headers.get("Content-Disposition");

        if (!disposition) {
            fileName = "download";
        } else {
            const utf8Match = disposition.match(/filename\*\s*=\s*UTF-8''([^;]+)/i);
            if (utf8Match && utf8Match[1]) {
                fileName = decodeURIComponent(utf8Match[1]);
            } else {
                fileName = "download";
            }
        }
        return res.blob().then(function(blob) {
                                return {
                                    blob: blob,
                                    fileName: fileName
                                };
                        });
    }).then (function (result) {
        const blobUrl = URL.createObjectURL(result.blob);
        const a = document.createElement("a");
        a.style.display = "none";
        a.href = blobUrl;
        a.download = result.fileName;

        document.body.appendChild(a);
        // 강제 클릭
        a.click();

        setTimeout(function () {
            URL.revokeObjectURL(
                blobUrl
            );
            document.body.removeChild(a);
        }, 100);     
    }).catch (function (error) {        
        $c.win.alert(error.message);

    });       
};

/**
 * @method
 * @name sendFileMultiUpload
 * @description 멀티 업로드 처리
 * @param {object} formData 전송 할 정보
 * @param {string} url 파일을 전송 할 URL
 * @param {object} callBack 응답을 받을 함수
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example
 */
scwin.sendFileMultiUpload = async function (formData, url, callBack) {

    const res = await fetch(url, {
        method: "POST",
        body: formData
    });

    const rtn = await res.json();
    console.log(rtn);
    callBack(rtn);

};

scwin.getCircleNumber = function (num)
{
    if((num >= 1) && (num <=20))
    {
        return String.fromCharCode(0x2460 + (num - 1));
    }

    return num;
}
